package scp_candidate.Factory_Dispatch_Coordinator

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Dock_Qualifier_Api {
  def id: Art.BridgeId
  def dock_snapshot_Id : Art.PortId
  def assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var assessment: Factory_Dispatch_Coordinator.Dock_Assessment.Type = $

  def put_assessment(value : Factory_Dispatch_Coordinator.Dock_Assessment.Type) : Unit = {
    Contract(
      Modifies(assessment),
      Ensures(
        assessment == value
      )
    )
    Spec {
      assessment = value
    }

    Art.putValue(assessment_Id, Factory_Dispatch_Coordinator.Dock_Assessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Dock_Qualifier_Initialization_Api (
  val id: Art.BridgeId,
  val dock_snapshot_Id : Art.PortId,
  val assessment_Id : Art.PortId) extends Dock_Qualifier_Api

@datatype class Dock_Qualifier_Operational_Api (
  val id: Art.BridgeId,
  val dock_snapshot_Id : Art.PortId,
  val assessment_Id : Art.PortId) extends Dock_Qualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var dock_snapshot: Factory_Dispatch_Coordinator.Dock_Snapshot = $

  def get_dock_snapshot() : Option[Factory_Dispatch_Coordinator.Dock_Snapshot] = {
    Contract(
      Ensures(
        Res == Some(dock_snapshot)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Dock_Snapshot] = Art.getValue(dock_snapshot_Id) match {
      case Some(Factory_Dispatch_Coordinator.Dock_Snapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port dock_snapshot.  Expecting 'Factory_Dispatch_Coordinator.Dock_Snapshot_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Dock_Snapshot]()
      case _ => None[Factory_Dispatch_Coordinator.Dock_Snapshot]()
    }
    return value
  }
}
